private val DarkBg=Color(0xFF06090B); private val DarkSurface=Color(0xFF0D1418); private val DarkTeal=Color(0xFF48D7C5); private val DarkText=Color(0xFFF5F8F8); private val DarkMuted=Color(0xFF8B9A9F); private val LightBg=Color(0xFFF4F7F7); private val LightSurface=Color.White; private val LightTeal=Color(0xFF087F73); private val LightText=Color(0xFF102024); private val LightMuted=Color(0xFF647277)
private class UiPrefs(context:Context){private val p=context.getSharedPreferences("cardiag_ui",Context.MODE_PRIVATE);var dark:Boolean get()=p.getBoolean("dark",true);set(v){p.edit().putBoolean("dark",v).apply()};var lang:String get()=p.getString("lang","fr")?:"fr";set(v){p.edit().putString("lang",v).apply()}}
private data class Copy(val home:String,val diagnostic:String,val garage:String,val history:String,val more:String,val smart:String,val search:String,val catalog:String,val models:String,val makes:String,val launch:String,val back:String)
private val FR=Copy("Accueil","Diagnostic","Garage","Historique","Plus","SMART VEHICLE DIAGNOSTICS","Rechercher une marque ou un modèle","Catalogue véhicules","MODÈLES","MARQUES","Lancer le diagnostic","Retour")
private val AR=Copy("الرئيسية","التشخيص","المرآب","السجل","المزيد","تشخيص السيارات الذكي","ابحث عن الماركة أو الموديل","كتالوج السيارات","الموديلات","الماركات","بدء التشخيص","رجوع")

@Composable fun CarDiagExactApp(){val ctx=LocalContext.current;val prefs=remember{UiPrefs(ctx)};var dark by remember{mutableStateOf(prefs.dark)};var lang by remember{mutableStateOf(prefs.lang)};var tab by remember{mutableIntStateOf(0)};var selected by remember{mutableStateOf<ExactVehicle?>(null)};var langDialog by remember{mutableStateOf(false)};val c=if(lang=="ar")AR else FR;val primary=if(dark)DarkTeal else LightTeal;val bg=if(dark)DarkBg else LightBg;val surface=if(dark)DarkSurface else LightSurface;val text=if(dark)DarkText else LightText;val muted=if(dark)DarkMuted else LightMuted;MaterialTheme(colorScheme=if(dark)darkColorScheme(primary=primary,background=bg,surface=surface,onSurface=text,onSurfaceVariant=muted)else lightColorScheme(primary=primary,background=bg,surface=surface,onSurface=text,onSurfaceVariant=muted)){CompositionLocalProvider(LocalLayoutDirection provides if(lang=="ar")LayoutDirection.Rtl else LayoutDirection.Ltr){if(selected!=null)ExactVehicleProfileScreen(model=UiModel(selected!!.id,selected!!.name,selected!!.imageUrl),onBack={selected=null})else Scaffold(containerColor=bg,bottomBar={NavigationBar(containerColor=surface){val labels=listOf(c.home,c.diagnostic,c.garage,c.history,c.more);val icons=listOf(Icons.Default.Home,Icons.Default.Build,Icons.Default.Garage,Icons.Default.History,Icons.Default.Settings);labels.forEachIndexed{i,l->NavigationBarItem(selected=tab==i,onClick={tab=i},icon={Icon(icons[i],l)},label={Text(l)})}}}){p->when(tab){0->HomeScreen(p,c,primary,surface,muted){selected=it};1->DiagnosticHub(p,c,primary,surface,muted);2->GarageScreen(p,c,primary,surface,muted){selected=it};3->HistoryScreen(p,c,primary,surface,muted);else->MoreScreen(p,c,dark,primary,surface,muted,{langDialog=true},{dark=!dark;prefs.dark=dark})}}}};if(langDialog)AlertDialog(onDismissRequest={langDialog=false},title={Text(if(lang=="ar")"اللغة"else"Langue")},text={Column{Text("Français",Modifier.fillMaxWidth().clickable{lang="fr";prefs.lang="fr";langDialog=false}.padding(14.dp));Text("العربية",Modifier.fillMaxWidth().clickable{lang="ar";prefs.lang="ar";langDialog=false}.padding(14.dp))}},confirmButton={TextButton(onClick={langDialog=false}){Text(c.back)}})}}

@Composable private fun Header(title:String,sub:String,primary:Color,muted:Color){Row(Modifier.fillMaxWidth().padding(20.dp),verticalAlignment=Alignment.CenterVertically){Box(Modifier.size(46.dp).clip(RoundedCornerShape(15.dp)).background(primary.copy(alpha=.14f)),contentAlignment=Alignment.Center){Icon(Icons.Default.DirectionsCar,null,tint=primary)};Spacer(Modifier.width(12.dp));Column{Text(title,style=MaterialTheme.typography.titleLarge,fontWeight=FontWeight.Black);Text(sub,color=muted,style=MaterialTheme.typography.labelSmall)}}}

@Composable private fun HomeScreen(p:PaddingValues,c:Copy,primary:Color,surface:Color,muted:Color,onVehicle:(ExactVehicle)->Unit){val scope=rememberCoroutineScope();var models by remember{mutableStateOf<List<ExactVehicle>>(emptyList())};var makes by remember{mutableStateOf<List<ExactMake>>(emptyList())};var q by remember{mutableStateOf("")};LaunchedEffect(Unit){scope.launch{models=runCatching{SupabaseClient.client.from("vehicle_models").select(Columns.list("id","make_id","name","year_from","year_to","generation","image_url")).decodeList<ExactVehicle>()}.getOrDefault(emptyList());makes=runCatching{SupabaseClient.client.from("vehicle_makes").select(Columns.list("id","name")).decodeList<ExactMake>()}.getOrDefault(emptyList())}};val filtered=models.filter{q.isBlank()||it.name.contains(q,true)||makes.firstOrNull{m->m.id==it.makeId}?.name?.contains(q,true)==true};LazyColumn(Modifier.fillMaxSize().padding(p),verticalArrangement=Arrangement.spacedBy(14.dp),contentPadding=PaddingValues(bottom=24.dp)){item{Header("CarDiag",c.smart,primary,muted)};item{Card(Modifier.fillMaxWidth().padding(16.dp),RoundedCornerShape(28.dp),colors=CardDefaults.cardColors(containerColor=surface)){Column(Modifier.padding(24.dp)){Text(c.smart,color=primary,fontWeight=FontWeight.Black);Text(if(c==AR)"سيارتك. بياناتك. تشخيصك."else"Votre voiture. Vos données. Votre diagnostic.",style=MaterialTheme.typography.headlineMedium,fontWeight=FontWeight.Black);Spacer(Modifier.height(14.dp));Button(onClick={filtered.firstOrNull()?.let(onVehicle)},enabled=filtered.isNotEmpty()){Text(c.launch)}}}};item{OutlinedTextField(q,{q=it},Modifier.fillMaxWidth().padding(horizontal=16.dp),singleLine=true,placeholder={Text(c.search)},leadingIcon={Icon(Icons.Default.Search,null)})};item{Text(c.catalog,Modifier.padding(horizontal=20.dp),style=MaterialTheme.typography.titleLarge,fontWeight=FontWeight.Black)};items(filtered.take(30),key={it.id}){v->VehicleCard(v,makes.firstOrNull{m->m.id==v.makeId}?.name?:"Vehicle",primary,surface,muted,onVehicle)}}}

@Composable private fun VehicleCard(v:ExactVehicle,make:String,primary:Color,surface:Color,muted:Color,onClick:(ExactVehicle)->Unit){Card(Modifier.fillMaxWidth().padding(horizontal=16.dp).clickable{onClick(v)},RoundedCornerShape(22.dp),colors=CardDefaults.cardColors(containerColor=surface)){Row(Modifier.padding(12.dp),verticalAlignment=Alignment.CenterVertically){AsyncImage(v.imageUrl,v.name,Modifier.size(90.dp).clip(RoundedCornerShape(14.dp)),contentScale=ContentScale.Crop);Spacer(Modifier.width(12.dp));Column{Text(make,color=primary,fontWeight=FontWeight.Bold);Text(v.name,fontWeight=FontWeight.Black);Text(listOfNotNull(v.generation,v.yearFrom?.toString(),v.yearTo?.toString()).joinToString(" • "),color=muted,style=MaterialTheme.typography.labelSmall)}}}}

@Composable private fun DiagnosticHub(p:PaddingValues,c:Copy,primary:Color,surface:Color,muted:Color){val ctx=LocalContext.current;fun open(a:Class<*>){ctx.startActivity(Intent(ctx,a))};Column(Modifier.fillMaxSize().padding(p).padding(20.dp),verticalArrangement=Arrangement.spacedBy(12.dp)){Header(c.diagnostic,c.smart,primary,muted);HubCard("OBD-II Scanner",Icons.Default.Build,primary,surface){open(ObdScannerActivity::class.java)};HubCard("Live Data",Icons.Default.Speed,primary,surface){open(LiveDataProActivity::class.java)};HubCard("DTC & Faults",Icons.Default.Warning,primary,surface){open(GuidedDiagnosisActivity::class.java)};HubCard("VIN Identity",Icons.Default.DirectionsCar,primary,surface){open(ObdScannerActivity::class.java)};HubCard("AI Diagnosis • Sans OBD",Icons.Default.Build,primary,surface){open(AiSymptomDiagnosisActivity::class.java)}}}
@Composable private fun HubCard(title:String,icon:androidx.compose.ui.graphics.vector.ImageVector,primary:Color,surface:Color,onClick:()->Unit){Card(Modifier.fillMaxWidth().clickable(onClick=onClick),RoundedCornerShape(20.dp),colors=CardDefaults.cardColors(containerColor=surface)){Row(Modifier.padding(18.dp),verticalAlignment=Alignment.CenterVertically){Icon(icon,null,tint=primary);Spacer(Modifier.width(14.dp));Text(title,Modifier.weight(1f),fontWeight=FontWeight.Black);Icon(Icons.Default.ChevronRight,null,tint=primary)}}}

@Composable private fun GarageScreen(p:PaddingValues,c:Copy,primary:Color,surface:Color,muted:Color,onVehicle:(ExactVehicle)->Unit){val scope=rememberCoroutineScope();var rows by remember{mutableStateOf<List<GarageVehicle>>(emptyList())};var models by remember{mutableStateOf<List<ExactVehicle>>(emptyList())};var makes by remember{mutableStateOf<List<ExactMake>>(emptyList())};var loading by remember{mutableStateOf(true)};var add by remember{mutableStateOf(false)};var error by remember{mutableStateOf<String?>(null)};fun load(){scope.launch{loading=true;val session=runCatching{SupabaseClient.client.auth.currentSessionOrNull()}.getOrNull();if(session==null){error=if(c==AR)"سجّل الدخول لإدارة سياراتك"else"Connectez-vous pour gérer votre garage";loading=false;return@launch};rows=runCatching{SupabaseClient.client.from("user_vehicles").select(Columns.list("id","model_id","make_id","nickname","vin","mileage","year","is_primary")).decodeList<GarageVehicle>()}.getOrElse{error=it.message;emptyList()};models=runCatching{SupabaseClient.client.from("vehicle_models").select(Columns.list("id","make_id","name","year_from","year_to","generation","image_url")).decodeList<ExactVehicle>()}.getOrDefault(emptyList());makes=runCatching{SupabaseClient.client.from("vehicle_makes").select(Columns.list("id","name")).decodeList<ExactMake>()}.getOrDefault(emptyList());loading=false}};LaunchedEffect(Unit){load()};Column(Modifier.fillMaxSize().padding(p).padding(20.dp),verticalArrangement=Arrangement.spacedBy(12.dp)){Header(c.garage,c.smart,primary,muted);Button(onClick={add=true},Modifier.fillMaxWidth()){Icon(Icons.Default.Add,null);Spacer(Modifier.width(8.dp));Text(if(c==AR)"إضافة سيارة"else"Ajouter un véhicule")};if(error!=null)Text(error!!,color=MaterialTheme.colorScheme.error);if(loading)CircularProgressIndicator(color=primary)else LazyColumn(verticalArrangement=Arrangement.spacedBy(10.dp)){items(rows,key={it.id}){r->val m=models.firstOrNull{it.id==r.modelId};val mk=makes.firstOrNull{it.id==r.makeId}?.name?:"";Card(Modifier.fillMaxWidth().clickable{m?.let(onVehicle)},RoundedCornerShape(20.dp),colors=CardDefaults.cardColors(containerColor=surface)){Row(Modifier.padding(12.dp),verticalAlignment=Alignment.CenterVertically){AsyncImage(m?.imageUrl,m?.name,Modifier.size(82.dp).clip(RoundedCornerShape(14.dp)),contentScale=ContentScale.Crop);Spacer(Modifier.width(12.dp));Column{Text(r.nickname?:m?.name?:"Vehicle",fontWeight=FontWeight.Black);Text("$mk • ${m?.name?:""}",color=muted);r.vin?.let{Text("VIN • $it",color=primary,style=MaterialTheme.typography.labelSmall)};r.mileage?.let{Text("$it km",color=muted,style=MaterialTheme.typography.labelSmall)}}}}}}};if(add)AlertDialog(onDismissRequest={add=false},title={Text(if(c==AR)"اختر سيارة"else"Choisir un véhicule")},text={LazyColumn(Modifier.heightIn(max=400.dp)){items(models.take(50),key={it.id}){m->Text(m.name,Modifier.fillMaxWidth().clickable{scope.launch{val uid=SupabaseClient.client.auth.currentSessionOrNull()?.user?.id;if(uid!=null)runCatching{SupabaseClient.client.from("user_vehicles").insert(GarageVehicleInsert(uid,m.makeId,m.id,m.name,rows.isEmpty()));add=false;load()}.onFailure{error=it.message}}}.padding(14.dp))}}},confirmButton={TextButton(onClick={add=false}){Text(c.back)}})}}

